package com.bank.clone;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Deep-copies a linked-account graph, handling cycles via an old->new map.
public class AccountGraphCloner {

    private static final Logger log = Logger.getLogger(AccountGraphCloner.class.getName());

    public Node clone(Node start) {
        if (start == null) return null;
        Node result = dfs(start, new HashMap<>());
        log.info("Cloned account graph starting at node " + start.val);
        return result;
    }

    private Node dfs(Node node, Map<Node, Node> clones) {
        Node existing = clones.get(node);
        if (existing != null) {
            return existing;         // already cloned → reuse (handles cycles)
        }
        Node copy = new Node(node.val);
        clones.put(node, copy);      // record BEFORE expanding neighbors
        for (Node nb : node.neighbors) {
            copy.neighbors.add(dfs(nb, clones));
        }
        return copy;
    }
}
