package com.bank.clone;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class CloneDemo {

    private static final Logger log = Logger.getLogger(CloneDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Clone Linked-Account Graph");
        // Build a cyclic graph: 1-2, 2-3, 3-1 (triangle)
        Node a = new Node(1), b = new Node(2), c = new Node(3);
        a.neighbors.add(b); b.neighbors.add(a);
        b.neighbors.add(c); c.neighbors.add(b);
        c.neighbors.add(a); a.neighbors.add(c);

        AccountGraphCloner cloner = new AccountGraphCloner();
        Node copy = cloner.clone(a);
        log.info("Copy root val=" + copy.val
                + " is distinct object: " + (copy != a)
                + ", neighbor count=" + copy.neighbors.size());
    }
}
